class GameAudio {
  ctx:AudioContext|null=null;lastCoin=0;lastStep=0;note=0;coinCombo=0;lastCoinTime=0;
  unlock(){try{this.ctx??=new AudioContext();void this.ctx.resume();}catch{}}
  tone(freq:number,duration:number,volume=.025,type:OscillatorType='sine',end?:number){if(!this.ctx||saved.muted)return;const c=this.ctx,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(freq,c.currentTime);if(end)o.frequency.exponentialRampToValueAtTime(end,c.currentTime+duration);g.gain.setValueAtTime(.0001,c.currentTime);g.gain.linearRampToValueAtTime(volume,c.currentTime+.009);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+duration);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+duration);}
  coin(){
    const t=performance.now();
    if(t-this.lastCoin<70)return;
    this.lastCoin=t;
    const gap=(t-this.lastCoinTime)/1000;
    this.lastCoinTime=t;
    if(gap>.45)this.coinCombo=0;else this.coinCombo=Math.min(7,this.coinCombo+1);
    const scale=[523.25,587.33,659.25,783.99,880.00,1046.50,1174.66,1318.51];
    const freq=scale[this.coinCombo];
    this.tone(freq,.14,.019,'sine',freq*1.12);
    if(this.coinCombo===7)setTimeout(()=>this.tone(1567.98,.24,.019,'sine',2093),40);
  }
  whoosh(dir:number){this.tone(dir>0?340:270,.08,.012,'triangle',dir>0?480:390);}
  jump(){this.tone(195,.12,.015,'sine',330);}
  land(){this.tone(85,.08,.026,'triangle',36);}
  slide(){this.tone(110,.12,.011,'triangle',55);}
  crash(){this.tone(105,.3,.045,'triangle',40);this.tone(60,.35,.04,'sawtooth',30);}
  power(){this.tone(523,.24,.022,'sine',784);setTimeout(()=>this.tone(784,.2,.02,'sine',1046),80);}
  boardActivate(){this.tone(440,.18,.025,'sine',880);setTimeout(()=>this.tone(659.25,.22,.025,'sine',1318.51),80);}
  boardBreak(){this.tone(260,.28,.045,'triangle',45);this.tone(130,.35,.05,'sawtooth',30);}
  graze(){this.tone(160,.16,.022,'triangle',75);}
  step(t:number){if(t-this.lastStep>.26){this.lastStep=t;this.tone(62,.035,.008,'triangle',42);}}
}
