const discovered=new Set<string>();const pools:Record<string,Item[]>={bus:[],rickshaw:[],barrier:[],arch:[],coin:[],magnet:[],boost:[]};const all:Item[]=[];pools.rooftop=[];
function createItem(key:string):Item{const obstacle=['bus','rickshaw','barrier','arch','rooftop'].includes(key);const root=key==='rooftop'?world.assets.rooftop():obstacle?world.obstacle(key as ObstacleKind):key==='coin'?world.coin():world.power(key as 'magnet'|'boost');const item:Item={root,type:obstacle?'obstacle':key as Item['type'],kind:obstacle?(key==='rooftop'?'bus':key) as ObstacleKind:undefined,active:false,width:root.metadata?.width??2.6,depth:root.metadata?.depth??.5,height:root.metadata?.height??1.4,phase:all.length*.63,counted:false,jumped:false,vehicleSpeed:0,previousZ:0,baseX:0,baseY:0,baseZ:0,ramp:key==='rooftop',entryRamp:key==='rooftop',exitRamp:false,grazed:false};if(item.ramp){const deck=MeshBuilder.CreateBox('walkable cargo deck',{width:item.width,height:.08,depth:item.depth},world.scene);deck.parent=root;deck.position.y=item.height;deck.material=world.mat('cargo deck','#987446');const ramp=MeshBuilder.CreateBox('loading ramp',{width:item.width,height:.12,depth:Math.hypot(12,item.height)},world.scene);ramp.parent=root;ramp.position.set(0,item.height/2,-item.depth/2-6);ramp.rotation.x=-Math.atan2(item.height,12);ramp.material=world.mat('loading ramp','#d6ae59');const exit=ramp.clone('exit ramp',root)!;exit.position.z=item.depth/2+6;exit.rotation.x=Math.atan2(item.height,12);exit.setEnabled(false);}root.setEnabled(false);pools[key].push(item);all.push(item);return item;}
