function spawnRow(z:number){
 const roofLane=Math.floor(rowIndex/8)%3,wave=trafficWave(rowIndex);
 const existing=all.filter(i=>i.active&&i.type==='obstacle').map(i=>({x:i.root.position.x,z:i.root.position.z,depth:i.depth+(i.ramp?24:0),kind:i.kind!,vehicleSpeed:i.vehicleSpeed}));
 if(!wave.reserve&&rowIndex>3&&rowIndex%8===4&&!existing.some(o=>(o.x===LANES[roofLane]||o.x===LANES[(roofLane+1)%3])&&(o.z+o.depth/2+4)/(speed+o.vehicleSpeed)>=(z-20)/speed)&&canPlaceTraffic({x:LANES[roofLane],z:z+20,kind:'bus',depth:80,vehicleSpeed:0},existing,speed)){
  const first=spawn('rooftop',roofLane,z),layout=convoyLayout(z,first.depth,rowIndex),bypass=(roofLane+1)%3;
  layout.centers.forEach((center,index)=>{const truck=index===0?first:spawn('rooftop',roofLane,center);truck.entryRamp=index===0;truck.exitRamp=index===layout.centers.length-1;for(const child of truck.root.getChildMeshes()){if(child.name==='loading ramp')child.setEnabled(truck.entryRamp);if(child.name==='exit ramp')child.setEnabled(truck.exitRamp);}
   const begin=index===0?-truck.depth/2-11:-truck.depth/2+.5;
   for(let local=begin;local<truck.depth/2+(truck.exitRamp?12:0);local+=1.8){const h=surfaceHeight(LANES[roofLane],local,{...truck,x:LANES[roofLane],ramp:truck.entryRamp})??truck.height;spawn('coin',roofLane,center+local,h+1.1);}
  });
  for(let pos=layout.entry;pos<=layout.exit;pos+=2.5)spawn('coin',bypass,pos,1.1);
  rowIndex++;nextRow=layout.exit+26;return;
 }
 if(wave.spawn){const bus={x:LANES[wave.lane],z,kind:'bus',depth:8.5,vehicleSpeed:ONCOMING_BUS_SPEED};if(canPlaceTraffic(bus,existing,speed))spawn('bus',wave.lane,z);}
 const row=streetRow(rowIndex++,runSeed),route=environmentAt(world.travel+z),open=route.kind!=='street'&&rowIndex%4===0;if(wave.reserve&&row.safeLane===wave.lane)row.safeLane=(wave.lane+1)%3;for(const o of row.obstacles)if(!open&&o.lane!==row.safeLane&&!(wave.reserve&&o.lane===wave.lane)&&!(o.kind==='bus'&&o.lane===Math.floor((rowIndex-1)/8)%3&&(rowIndex-1)%8<4)){const candidate={x:LANES[o.lane],z,kind:o.kind,depth:o.kind==='bus'?8.5:o.kind==='rickshaw'?5:.5,vehicleSpeed:o.kind==='bus'?ONCOMING_BUS_SPEED:0};const existing=all.filter(i=>i.active&&i.type==='obstacle').map(i=>({x:i.root.position.x,z:i.root.position.z,kind:i.kind!,width:i.width,depth:i.depth+(i.ramp?24:0),vehicleSpeed:i.vehicleSpeed}));if(canPlaceTraffic(candidate,existing,speed))spawn(o.kind,o.lane,z);}for(let i=0;i<7;i++)spawn('coin',row.safeLane,z-7+i*2.1,1.15);if(rowIndex%4===0)spawn(rowIndex%8===0?'boost':'magnet',row.safeLane,z+9,1.35);if(open)for(let i=0;i<3;i++)spawn('coin',(row.safeLane+1)%3,z+i*2.1,1.15);nextRow=z+(route.kind==='coast'?34:route.kind==='street'?28:31);}
