async function init(){try{await Promise.race([document.fonts.load('bold 60px "Noto Nastaliq Urdu"'),new Promise(r=>setTimeout(r,4500))]);world=new KarachiWorld($<HTMLCanvasElement>('world'),saved.selectedCharacter);world.quality(saved.lowGraphics);await world.assets.ready;for(const [key,count] of Object.entries({bus:5,rickshaw:5,barrier:7,arch:7,coin:75,magnet:2,boost:2,rooftop:2}))for(let i=0;i<count;i++)createItem(key);resetScene(0);const loadingText=$('loading').querySelector('p');if(loadingText)loadingText.textContent='LOADING YOUR 3D CHARACTERS…';await Promise.all([world.runner.ready,world.pursuer.ready]);await world.scene.whenReadyAsync();let previous=performance.now();world.engine.runRenderLoop(()=>{const now=performance.now(),dt=Math.min((now-previous)/1000,.04);frameWallDt=(now-previous)/1000;previous=now;update(dt,now);});$('loading').classList.add('hidden');$<HTMLButtonElement>('play-button').disabled=false;$<HTMLButtonElement>('settings-button').disabled=false;
  void document.fonts.ready.then(()=>{if(!document.fonts.check('60px "Noto Nastaliq Urdu"'))return;const fresh=world.makeSigns();world.signMat.diffuseTexture?.dispose();world.signMat.diffuseTexture=fresh.diffuseTexture;fresh.diffuseTexture=null;fresh.dispose();});
  const context=(document as Document & {modelContext?:{registerTool:(tool:unknown)=>void}}).modelContext;if(context?.registerTool)try{context.registerTool({name:'get_karachi_run_progress',description:'Read saved Karachi Run records, challenge progress, current district, and run state.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:(input:unknown)=>{if(input===null||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');return {coins:saved.coins,best:saved.best,runs:saved.runs,mode,speed:Number(speed.toFixed(2)),speedPercent:Math.round(speed/14*100),distance:Math.floor(distance),district:routeAt(world.travel).name,revives,challenge:missionFor(saved.missionIndex).label,challengeProgress:Math.floor(saved.missionProgress),characterModels:[world.runner.source,world.pursuer.source],oncomingBuses:all.filter(i=>i.active&&i.vehicleSpeed>0).length,chaserBlocked:world.chaserBlocked};}});}catch{}
}catch(error){console.error(error);$('loading').innerHTML='<div class="brand-mark">K</div><p>THE STREET COULDN’T LOAD</p><div style="max-width:290px;text-align:center;line-height:1.6;font-size:14px">The 3D scene or character files could not load. Check the connection and try again.</div><button class="play-button" id="reload-button">TRY AGAIN ↗</button>';$('reload-button').onclick=()=>location.reload();}}
